#!/usr/bin/python3

import pyrob.core as rob
import random

# Порядок вариантов: один раз перемешиваем при загрузке модуля — без повторений в пределах 0..1
_variant_order = list(range(2))
random.shuffle(_variant_order)

class Task:
    CHECKS = 2

    def load_level(self, n):
        idx = _variant_order[n % len(_variant_order)]
        if idx == 0:
            rob.set_field_size(10, 20)
            rob.goto(5, 1)
            rob.put_wall(bottom=True)
            rob.goto(5, 2)
            rob.put_wall(bottom=True)
            rob.goto(5, 3)
            rob.put_wall(bottom=True)
            rob.goto(5, 4)
            rob.put_wall(bottom=True)
            rob.goto(5, 5)
            rob.put_wall(bottom=True)
            rob.goto(5, 6)
            rob.put_wall(bottom=True)
            rob.goto(5, 7)
            rob.put_wall(bottom=True)
            rob.goto(5, 8)
            rob.put_wall(bottom=True)
            rob.goto(6, 0)
            rob.put_wall(right=True)
            rob.goto(6, 1)
            rob.put_wall(bottom=True)
            rob.goto(6, 2)
            rob.put_wall(bottom=True)
            rob.goto(6, 3)
            rob.put_wall(bottom=True)
            rob.goto(6, 4)
            rob.put_wall(bottom=True)
            rob.goto(6, 5)
            rob.put_wall(bottom=True)
            rob.goto(6, 6)
            rob.put_wall(bottom=True)
            rob.goto(6, 7)
            rob.put_wall(bottom=True)
            rob.goto(6, 8)
            rob.put_wall(right=True)
            rob.goto(7, 7)
            rob.put_wall(right=True)
            rob.goto(7, 8)
            rob.put_wall(right=True)
            rob.goto(8, 7)
            rob.put_wall(right=True)
            rob.goto(8, 8)
            rob.put_wall(right=True)
            rob.goto(9, 7)
            rob.put_wall(right=True)
            rob.goto(9, 8)
            rob.put_wall(right=True)
            rob.set_parking_cell(6, 1)
            rob.goto(9, 8)
        elif idx == 1:
            rob.set_field_size(10, 20)
            rob.goto(3, 15)
            rob.put_wall(bottom=True)
            rob.goto(3, 16)
            rob.put_wall(bottom=True)
            rob.goto(3, 17)
            rob.put_wall(bottom=True)
            rob.goto(4, 14)
            rob.put_wall(right=True)
            rob.goto(4, 16)
            rob.put_wall(bottom=True)
            rob.goto(4, 17)
            rob.put_wall(right=True, bottom=True)
            rob.goto(5, 14)
            rob.put_wall(right=True)
            rob.goto(5, 15)
            rob.put_wall(right=True)
            rob.goto(6, 14)
            rob.put_wall(right=True)
            rob.goto(6, 15)
            rob.put_wall(right=True)
            rob.goto(7, 14)
            rob.put_wall(right=True)
            rob.goto(7, 15)
            rob.put_wall(right=True)
            rob.goto(8, 14)
            rob.put_wall(right=True)
            rob.goto(8, 15)
            rob.put_wall(right=True)
            rob.goto(9, 14)
            rob.put_wall(right=True)
            rob.goto(9, 15)
            rob.put_wall(right=True)
            rob.set_parking_cell(4, 17)
            rob.goto(9, 15)

    def check_solution(self):
        return rob.is_parking_point()
